     5	/**
     6	 * Como o hóspede se identifica e qual documento ele recebe. Um novo jeito de reservar
     7	 * (ex.: agência de turismo) é uma nova implementação, registrada em {@link IdentityTypes}.
     8	 */
     9	public interface Identity {
    10	    /** Campos de identificação desta reserva (só os que se aplicam). */
    11	    Map<String, String> fields();
    12	
    13	    /** Título do documento no JSON. */
