     3	import java.util.List;
     4	import java.util.Map;
     5	
     6	/** Reconhece um jeito de identificação a partir dos campos do corpo da requisição. */
     7	public interface IdentityType {
     8	    /** Nomes dos campos do JSON que pertencem a este tipo. */
     9	    List<String> fieldNames();
    10	
    11	    /** Cria a identidade; recebe todos os campos do tipo, já preenchidos. */
