=== IdentityTypes.java
     1	package br.com.mealta.pousada;
     2	
     3	import java.util.ArrayList;
     4	import java.util.LinkedHashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	/** Registro dos jeitos de se identificar. Um novo tipo entra só na lista TYPES. */
     9	public final class IdentityTypes {
    10	    private static final List<IdentityType> TYPES =
    11	            List.of(CpfIdentity.TYPE, CnpjIdentity.TYPE, PassportIdentity.TYPE);
    12	
    13	    private IdentityTypes() {}
    14	
    15	    /** Todos os campos de identificação, na ordem do registro. */
    16	    public static List<String> allFieldNames() {
    17	        List<String> names = new ArrayList<>();
    18	        TYPES.forEach(t -> names.addAll(t.fieldNames()));
    19	        return names;
    20	    }
    21	
    22	    /** Campos de identificação de uma reserva: os que não se aplicam vêm null. */
    23	    public static Map<String, String> view(Identity identity) {
    24	        Map<String, String> view = new LinkedHashMap<>();
    25	        allFieldNames().forEach(n -> view.put(n, null));
    26	        view.putAll(identity.fields());
    27	        return view;
    28	    }
    29	
    30	    /** Exige exatamente um tipo, com todos os seus campos preenchidos. */
    31	    public static Identity parse(Map<String, Object> body) {
    32	        Identity found = null;
    33	        for (IdentityType type : TYPES) {
    34	            Map<String, String> values = new LinkedHashMap<>();
    35	            for (String name : type.fieldNames()) {
    36	                Object raw = body.get(name);
    37	                if (raw == null) continue;
    38	                if (!(raw instanceof String s)) {
    39	                    throw DomainException.invalid("Campo " + name + " deve ser texto");
    40	                }
    41	                if (!s.isBlank()) values.put(name, s.trim());
    42	            }
    43	            if (values.isEmpty()) continue;
    44	            if (found != null) {
    45	                throw DomainException.invalid("Informe apenas um jeito de identificação");
    46	            }
    47	            if (values.size() != type.fieldNames().size()) {
    48	                throw DomainException.invalid("Identificação incompleta: informe " + type.fieldNames());
    49	            }
    50	            found = type.create(values);
    51	        }
    52	        if (found == null) {
    53	            throw DomainException.invalid("Informe CPF, CNPJ com razão social ou passaporte com país");
    54	        }
    55	        return found;
    56	    }
    57	}
=== CpfIdentity.java
     1	package br.com.mealta.pousada;
     2	
     3	import java.util.LinkedHashMap;
     4	import java.util.List;
     5	import java.util.Map;
     6	
     7	/** Pessoa com CPF: recebe o comprovante de reserva. */
     8	public record CpfIdentity(String cpf) implements Identity {
     9	    public static final IdentityType TYPE = new IdentityType() {
    10	        public List<String> fieldNames() { return List.of("guestCpf"); }
    11	        public Identity create(Map<String, String> v) { return new CpfIdentity(v.get("guestCpf")); }
    12	    };
    13	
    14	    public Map<String, String> fields() {
    15	        Map<String, String> f = new LinkedHashMap<>();
    16	        f.put("guestCpf", cpf);
    17	        return f;
    18	    }
    19	
    20	    public String title() { return "Comprovante de reserva"; }
    21	
    22	    public String render(DocumentData d) {
    23	        List<String> lines = new java.util.ArrayList<>();
    24	        lines.add("Comprovante de reserva nº " + d.reservationId());
    25	        lines.add("Hóspede: " + d.guestName() + " (CPF " + cpf + ")");
    26	        lines.addAll(PtBrLayout.details(d, false));
    27	        return String.join("\n", lines);
    28	    }
    29	}
