     9	/** Empresa com CNPJ: recebe a fatura de hospedagem, com ISS retido. */
    10	public record CnpjIdentity(String cnpj, String companyName) implements Identity {
    11	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    12	
    13	    public static final IdentityType TYPE = new IdentityType() {
    14	        public List<String> fieldNames() { return List.of("companyCnpj", "companyName"); }
    15	        public Identity create(Map<String, String> v) {
    16	            return new CnpjIdentity(v.get("companyCnpj"), v.get("companyName"));
    17	        }
    18	    };
    19	
    20	    public Map<String, String> fields() {
    21	        Map<String, String> f = new LinkedHashMap<>();
    22	        f.put("companyCnpj", cnpj);
    23	        f.put("companyName", companyName);
    24	        return f;
    25	    }
    26	
    27	    public String title() { return "Fatura de hospedagem"; }
    28	
    29	    public String render(DocumentData d) {
    30	        List<String> lines = new ArrayList<>();
    31	        lines.add("Fatura de hospedagem nº " + d.reservationId());
    32	        lines.add("Empresa: " + companyName + " (CNPJ " + cnpj + ")");
    33	        lines.addAll(PtBrLayout.details(d, true));
    34	        lines.add("ISS retido (5%): " + Money.brl(Money.round(d.total().multiply(ISS_RATE))));
    35	        return String.join("\n", lines);
    36	    }
    37	}
