     9	public record PassportIdentity(String passport, String country) implements Identity {
    10	    public static final IdentityType TYPE = new IdentityType() {
    11	        public List<String> fieldNames() { return List.of("guestPassport", "guestCountry"); }
    12	        public Identity create(Map<String, String> v) {
    13	            return new PassportIdentity(v.get("guestPassport"), v.get("guestCountry"));
    14	        }
    15	    };
    16	
    17	    public Map<String, String> fields() {
    18	        Map<String, String> f = new LinkedHashMap<>();
    19	        f.put("guestPassport", passport);
    20	        f.put("guestCountry", country);
    21	        return f;
    22	    }
    23	
    24	    public String title() { return "Booking receipt"; }
    25	
    26	    public String render(DocumentData d) {
    27	        List<String> lines = new ArrayList<>();
    28	        lines.add("Booking receipt no. " + d.reservationId());
    29	        lines.add("Guest: " + d.guestName() + " (passport " + passport + ", " + country + ")");
    30	        lines.add("Room: " + d.roomNumber() + " (" + d.roomType() + ")");
    31	        lines.add("Check-in: " + d.checkIn() + " | Check-out: " + d.checkOut()
    32	                + " | " + d.nights() + (d.nights() == 1 ? " night" : " nights"));
    33	        lines.add("Nights: " + Money.brlEnglish(d.subtotal()));
    34	        if (d.hasDiscount()) {
    35	            lines.add("Discount: " + Money.brlEnglish(d.discount()));
    36	        }
    37	        lines.add("Total: " + Money.brlEnglish(d.total()));
    38	        return String.join("\n", lines);
    39	    }
    40	}
