     1	package br.com.mealta.pousada;
     2	
     3	import java.time.LocalDate;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.Map;
     7	import java.util.TreeMap;
     8	
     9	public class ReservationService {
    10	    private final Map<Integer, Room> rooms = new TreeMap<>();
    11	    private final Map<Long, Reservation> reservations = new TreeMap<>();
    12	    private final Outbox outbox;
    13	
    14	    public ReservationService(Outbox outbox) {
    15	        this.outbox = outbox;
    16	        for (Room r : List.of(new Room(101, RoomType.STANDARD), new Room(102, RoomType.STANDARD),
    17	                new Room(201, RoomType.DELUXE), new Room(202, RoomType.DELUXE),
    18	                new Room(301, RoomType.SUITE))) {
    19	            rooms.put(r.number(), r);
    20	        }
    21	    }
    22	
    23	    public List<Room> rooms() {
    24	        return new ArrayList<>(rooms.values());
