     9	public final class Reports {
    10	    private Reports() {}
    11	
    12	    public static String occupancy(LocalDate night, List<Reservation> all, List<Room> rooms) {
    13	        List<Reservation> occupying = all.stream()
    14	                .filter(r -> r.occupiesNight(night))
    15	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()).thenComparingLong(Reservation::id))
    16	                .toList();
    17	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    18	        for (Reservation r : occupying) {
    19	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id())
    20	                    .append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    21	        }
    22	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    23	        return csv.append("total,").append(occupiedRooms).append('/').append(rooms.size()).append('\n').toString();
    24	    }
    25	
    26	    public static String revenue(YearMonth month, List<Reservation> all) {
    27	        List<Reservation> kept = all.stream()
    28	                .filter(r -> YearMonth.from(r.checkIn()).equals(month) && r.retained().signum() > 0)
    29	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    30	                .toList();
    31	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    32	        BigDecimal total = Money.round(BigDecimal.ZERO);
    33	        for (Reservation r : kept) {
    34	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn())
    35	                    .append(',').append(r.checkOut()).append(',').append(r.status())
    36	                    .append(',').append(r.retained().toPlainString()).append('\n');
    37	            total = total.add(r.retained());
    38	        }
    39	        return csv.append("total,").append(total.toPlainString()).append('\n').toString();
    40	    }
    41	}
